import { db } from "../lib/db";
import { REVENUE_USER_WHERE } from "../lib/admin-metrics";

const DAY_MS = 86_400_000;
function daysAgo(n: number) {
  return new Date(Date.now() - n * DAY_MS);
}
function fmt(d: Date) {
  return d.toISOString().slice(0, 10);
}
function money(c: number | null | undefined) {
  if (c == null) return "null";
  return `$${(c / 100).toFixed(2)}`;
}

async function main() {
  console.log("=== NOW:", new Date().toISOString(), "===\n");

  // ---------- 1. Weekly signup cohorts + conversion to first paid server ----------
  // Real-customer filter, same as retention/revenue views.
  const WEEKS = 10;
  console.log(`--- Weekly signup cohorts (last ${WEEKS} weeks), CUSTOMER role, excludeFromRevenue:false ---`);
  console.log("week_start | signups | had_any_server | pct_any_server | had_paid_server | pct_paid | had_free_mc | pct_free_mc");

  type Row = {
    weekStart: string;
    signups: number;
    anyServer: number;
    paidServer: number;
    freeServer: number;
  };
  const rows: Row[] = [];

  for (let w = WEEKS - 1; w >= 0; w--) {
    const start = daysAgo((w + 1) * 7);
    const end = daysAgo(w * 7);
    const users = await db.user.findMany({
      where: {
        role: "CUSTOMER",
        excludeFromRevenue: false,
        createdAt: { gte: start, lt: end },
      },
      select: { id: true },
    });
    const ids = users.map((u) => u.id);
    let anyServer = 0;
    let paidServer = 0;
    let freeServer = 0;
    if (ids.length) {
      const servers = await db.server.findMany({
        where: { userId: { in: ids } },
        select: { userId: true, isFree: true },
      });
      const byUser = new Map<string, { any: boolean; paid: boolean }>();
      for (const s of servers) {
        const cur = byUser.get(s.userId) ?? { any: false, paid: false };
        cur.any = true;
        if (!s.isFree) cur.paid = true;
        byUser.set(s.userId, cur);
      }
      anyServer = [...byUser.values()].filter((v) => v.any).length;
      paidServer = [...byUser.values()].filter((v) => v.paid).length;

      const freeMc = await db.freeMinecraftServer.findMany({
        where: { userId: { in: ids } },
        select: { userId: true },
      });
      freeServer = new Set(freeMc.map((f) => f.userId)).size;
    }
    rows.push({ weekStart: fmt(start), signups: ids.length, anyServer, paidServer, freeServer });
    console.log(
      `${fmt(start)} | ${ids.length} | ${anyServer} | ${ids.length ? ((anyServer / ids.length) * 100).toFixed(1) : "0.0"}% | ${paidServer} | ${ids.length ? ((paidServer / ids.length) * 100).toFixed(1) : "0.0"}% | ${freeServer} | ${ids.length ? ((freeServer / ids.length) * 100).toFixed(1) : "0.0"}%`
    );
  }

  // Aggregate: last 7d, last 14d vs prior 28d (weeks -8..-2 roughly) baseline
  async function cohortStats(startDaysAgo: number, endDaysAgo: number) {
    const start = daysAgo(startDaysAgo);
    const end = daysAgo(endDaysAgo);
    const users = await db.user.findMany({
      where: { role: "CUSTOMER", excludeFromRevenue: false, createdAt: { gte: start, lt: end } },
      select: { id: true },
    });
    const ids = users.map((u) => u.id);
    if (!ids.length) return { start: fmt(start), end: fmt(end), signups: 0, any: 0, paid: 0 };
    const servers = await db.server.findMany({ where: { userId: { in: ids } }, select: { userId: true, isFree: true } });
    const byUser = new Map<string, { any: boolean; paid: boolean }>();
    for (const s of servers) {
      const cur = byUser.get(s.userId) ?? { any: false, paid: false };
      cur.any = true;
      if (!s.isFree) cur.paid = true;
      byUser.set(s.userId, cur);
    }
    const any = [...byUser.values()].filter((v) => v.any).length;
    const paid = [...byUser.values()].filter((v) => v.paid).length;
    return { start: fmt(start), end: fmt(end), signups: ids.length, any, paid };
  }

  console.log("\n--- Aggregate cohort comparison ---");
  const last7 = await cohortStats(7, 0);
  const last14 = await cohortStats(14, 0);
  const prior2_4w = await cohortStats(28, 14); // the 2 weeks before the last 14 days
  const prior4_8w = await cohortStats(56, 28); // 4-8 weeks ago baseline
  const prior8_12w = await cohortStats(84, 56);
  for (const [label, r] of [
    ["Last 7 days", last7],
    ["Last 14 days", last14],
    ["Prior 14-28 days ago (baseline A)", prior2_4w],
    ["Prior 28-56 days ago (baseline B)", prior4_8w],
    ["Prior 56-84 days ago (baseline C)", prior8_12w],
  ] as const) {
    const pctAny = r.signups ? ((r.any / r.signups) * 100).toFixed(1) : "n/a";
    const pctPaid = r.signups ? ((r.paid / r.signups) * 100).toFixed(1) : "n/a";
    console.log(`${label} [${r.start} .. ${r.end}]: signups=${r.signups} any-server=${r.any} (${pctAny}%) paid-server=${r.paid} (${pctPaid}%)`);
  }

  // ---------- 2. Pricing-change audit trail ----------
  console.log("\n--- AuditLog: plan/gameplan price-related admin actions, last 45 days ---");
  const planAudits = await db.auditLog.findMany({
    where: {
      createdAt: { gte: daysAgo(45) },
      action: { in: ["admin.save_plan", "gameplan.update", "gameplan.create", "gameplan.toggle", "gameplan.delete"] },
    },
    orderBy: { createdAt: "asc" },
    select: { createdAt: true, action: true, detail: true, userId: true },
  });
  for (const a of planAudits) {
    console.log(`${a.createdAt.toISOString()} | ${a.action} | ${a.detail}`);
  }
  console.log(`(${planAudits.length} rows)`);

  // ---------- 3. Current catalog snapshot ----------
  console.log("\n--- Current Plan (VPS) catalog ---");
  const plans = await db.plan.findMany({ orderBy: { sortOrder: "asc" } });
  for (const p of plans) {
    console.log(
      `${p.slug} | regular=${money(p.priceCents)}/mo | intro=${money(p.introPriceCents)} for ${p.introTermMonths ?? "whole first term"} mo | active=${p.active}`
    );
  }

  console.log("\n--- Current GamePlan catalog (sample, active only) ---");
  const gamePlans = await db.gamePlan.findMany({ where: { active: true }, orderBy: [{ gameFamily: "asc" }, { sortOrder: "asc" }] });
  for (const g of gamePlans) {
    console.log(
      `${g.gameFamily} | ${g.name} | regular=${money(g.priceCents)}/${g.termMonths}mo | intro=${money(g.introPriceCents)} for ${g.introTermMonths ?? "whole first term"} mo`
    );
  }

  // ---------- 4. Grandfathering coverage on recent servers ----------
  console.log("\n--- grandfatheredRenewalCents coverage on servers created in last 30 days ---");
  const recentServers = await db.server.findMany({
    where: { createdAt: { gte: daysAgo(30) } },
    select: { id: true, createdAt: true, isFree: true, grandfatheredRenewalCents: true, planId: true, gamePlanId: true },
  });
  const withGF = recentServers.filter((s) => s.grandfatheredRenewalCents != null).length;
  console.log(`total recent servers=${recentServers.length}, with grandfatheredRenewalCents set=${withGF}`);

