import { db } from "../lib/db";

const DAY_MS = 86_400_000;
function daysAgo(n: number) {
  return new Date(Date.now() - n * DAY_MS);
}
function fmt(d: Date) {
  return d.toISOString().slice(0, 10);
}

async function main() {
  console.log("=== NOW:", new Date().toISOString(), "===\n");

  // ---------- Typical signup -> first server lag, across ALL converted customers ----------
  console.log("--- Signup -> first server lag, converted customers (all time), CUSTOMER role ---");
  const convertedUsers = await db.user.findMany({
    where: { role: "CUSTOMER", excludeFromRevenue: false, servers: { some: {} } },
    select: { id: true, createdAt: true, servers: { select: { createdAt: true }, orderBy: { createdAt: "asc" }, take: 1 } },
  });
  const lagsHours: number[] = [];
  for (const u of convertedUsers) {
    const first = u.servers[0]?.createdAt;
    if (!first) continue;
    const lagH = (first.getTime() - u.createdAt.getTime()) / 3_600_000;
    lagsHours.push(lagH);
  }
  lagsHours.sort((a, b) => a - b);
  const pct = (p: number) => lagsHours[Math.floor((lagsHours.length - 1) * p)];
  console.log(`n=${lagsHours.length}`);
  if (lagsHours.length) {
    console.log(`p25=${pct(0.25).toFixed(1)}h p50(median)=${pct(0.5).toFixed(1)}h p75=${pct(0.75).toFixed(1)}h p90=${pct(0.9).toFixed(1)}h`);
    const within24h = lagsHours.filter((h) => h <= 24).length;
    const within72h = lagsHours.filter((h) => h <= 72).length;
    console.log(`within 24h of signup: ${within24h}/${lagsHours.length} (${((within24h / lagsHours.length) * 100).toFixed(1)}%)`);
    console.log(`within 72h of signup: ${within72h}/${lagsHours.length} (${((within72h / lagsHours.length) * 100).toFixed(1)}%)`);
  }

  // ---------- Daily signups + same-cohort deploy-within-72h rate, last 35 days ----------
  console.log("\n--- Daily signup cohorts + deploy-within-72h rate, last 35 days ---");
  console.log("(cohorts within the last 3 days are marked PARTIAL — not enough time has elapsed yet to judge)");
  console.log("date | signups | deployed_within_72h | pct | deployed_ever_so_far | pct_ever");

  for (let d = 34; d >= 0; d--) {
    const start = daysAgo(d + 1);
    const end = daysAgo(d);
    const users = await db.user.findMany({
      where: { role: "CUSTOMER", excludeFromRevenue: false, createdAt: { gte: start, lt: end } },
      select: { id: true, createdAt: true },
    });
    const ids = users.map((u) => u.id);
    let within72 = 0;
    let everSoFar = 0;
    if (ids.length) {
      const servers = await db.server.findMany({
        where: { userId: { in: ids } },
        select: { userId: true, createdAt: true },
      });
      const firstByUser = new Map<string, Date>();
      for (const s of servers) {
        const cur = firstByUser.get(s.userId);
        if (!cur || s.createdAt < cur) firstByUser.set(s.userId, s.createdAt);
      }
      for (const u of users) {
        const first = firstByUser.get(u.id);
        if (first) {
          everSoFar++;
          if (first.getTime() - u.createdAt.getTime() <= 72 * 3_600_000) within72++;
        }
      }
    }
    const partial = d < 3 ? " PARTIAL" : "";
    console.log(
      `${fmt(start)} | ${ids.length} | ${within72} | ${ids.length ? ((within72 / ids.length) * 100).toFixed(1) : "0.0"}% | ${everSoFar} | ${ids.length ? ((everSoFar / ids.length) * 100).toFixed(1) : "0.0"}%${partial}`
    );
  }

  // ---------- Same but split cleanly around the 2026-09-17 grandfather/pricing commit ----------
  console.log("\n--- Clean before/after split around 2026-09-17 04:00 UTC (grandfather program + wizard copy change) ---");
  const cutover = new Date("2026-09-17T04:00:00.000Z");
  async function windowStats(start: Date, end: Date, label: string) {
    const users = await db.user.findMany({
      where: { role: "CUSTOMER", excludeFromRevenue: false, createdAt: { gte: start, lt: end } },
      select: { id: true, createdAt: true },
    });
    const ids = users.map((u) => u.id);
    let everSoFar = 0;
    let within72 = 0;
    if (ids.length) {
      const servers = await db.server.findMany({ where: { userId: { in: ids } }, select: { userId: true, createdAt: true } });
      const firstByUser = new Map<string, Date>();
      for (const s of servers) {
        const cur = firstByUser.get(s.userId);
        if (!cur || s.createdAt < cur) firstByUser.set(s.userId, s.createdAt);
      }
      for (const u of users) {
        const first = firstByUser.get(u.id);
        if (first) {
          everSoFar++;
          if (first.getTime() - u.createdAt.getTime() <= 72 * 3_600_000) within72++;
        }
      }
    }
    console.log(`${label} [${start.toISOString()} .. ${end.toISOString()}]: signups=${ids.length} deployed_so_far=${everSoFar} (${ids.length ? ((everSoFar / ids.length) * 100).toFixed(1) : "n/a"}%) within72h=${within72} (${ids.length ? ((within72 / ids.length) * 100).toFixed(1) : "n/a"}%)`);
  }
  await windowStats(new Date(cutover.getTime() - 7 * DAY_MS), cutover, "7 days BEFORE cutover");
  await windowStats(cutover, new Date(cutover.getTime() + 4 * DAY_MS), "days 0-4 AFTER cutover (has had time to deploy)");
  await windowStats(new Date(cutover.getTime() + 4 * DAY_MS), new Date(), "most recent (still accruing, partial)");

  console.log("\nDONE");
}

main()
  .catch((e) => {
    console.error("SCRIPT ERROR", e);
    process.exitCode = 1;
  })
  .finally(async () => {
    await db.$disconnect();
  });

