import { db } from "../lib/db";

async function windowStats(start: Date, end: Date, label: string) {
  const users = await db.user.findMany({
    where: { role: "CUSTOMER", excludeFromRevenue: false, createdAt: { gte: start, lt: end } },
    select: { id: true, createdAt: true },
  });
  const ids = users.map((u) => u.id);
  let everSoFar = 0;
  if (ids.length) {
    const servers = await db.server.findMany({ where: { userId: { in: ids } }, select: { userId: true } });
    everSoFar = new Set(servers.map((s) => s.userId)).size;
  }
  console.log(
    `${label} [${start.toISOString()} .. ${end.toISOString()}]: signups=${ids.length} deployed_so_far=${everSoFar} (${ids.length ? ((everSoFar / ids.length) * 100).toFixed(1) : "n/a"}%)`
  );
}

async function main() {
  // The window where marketing pages showed the new (80% higher) price with
  // NO intro framing while checkout already showed the correct intro price.
  await windowStats(new Date("2026-09-17T04:33:00.000Z"), new Date("2026-09-19T01:32:00.000Z"), "Marketing-price-mismatch window");
  // Bracket immediately before and after for comparison.
  await windowStats(new Date("2026-09-15T04:33:00.000Z"), new Date("2026-09-17T04:33:00.000Z"), "2 days BEFORE mismatch window");
  await windowStats(new Date("2026-09-19T01:32:00.000Z"), new Date("2026-09-21T01:32:00.000Z"), "2 days AFTER mismatch window (fixed)");
  await db.$disconnect();
}
main().catch((e) => {
  console.error(e);
  process.exitCode = 1;
});
